import{useMemo,useState}from'react';import{Link}from'react-router-dom';import{Download,FileUp,Plus,Search,Trash2,Check,AlertCircle,ShoppingBag}from'lucide-react';import{products,Product}from'../data/products';import{useStore}from'../context/Store';
type Row={id:number;query:string;product?:Product;qty:number};
export default function QuickOrder(){const[rows,setRows]=useState<Row[]>([{id:1,query:'',qty:1},{id:2,query:'',qty:1},{id:3,query:'',qty:1}]);const[uploaded,setUploaded]=useState('');const{addCart,user,showToast}=useStore();const subtotal=useMemo(()=>rows.reduce((a,r)=>a+(r.product?r.product.price*r.product.casePack*r.qty:0),0),[rows]);const update=(id:number,data:Partial<Row>)=>setRows(r=>r.map(x=>x.id===id?{...x,...data}:x));const find=(id:number,q:string)=>{const p=products.find(x=>x.sku.toLowerCase()===q.toLowerCase())||products.find(x=>(x.name+' '+x.brand).toLowerCase().includes(q.toLowerCase()));update(id,{query:q,product:q.length>2?p:undefined})};const submit=()=>{const valid=rows.filter(r=>r.product);if(!valid.length)return showToast('Add at least one valid SKU');valid.forEach(r=>addCart(r.product!,Math.max(r.product!.moq,r.qty)));showToast(`${valid.length} product lines added to order`)};const download=()=>{const blob=new Blob(['SKU,CASE_QUANTITY\nGU-4100,1\n'],{type:'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='meridian-quick-order-template.csv';a.click();URL.revokeObjectURL(a.href)};return <div className="quick-order-page"><section className="quick-order-hero"><div className="container"><span className="eyebrow">PROCUREMENT WORKSPACE</span><h1>Quick order by SKU</h1><p>Build large, repeat orders without browsing the full catalog. Enter product references, set case quantities or upload a prepared CSV file.</p><div><span><Check/> Exact SKU and product matching</span><span><Check/> Case and MOQ validation</span><span><Check/> Account-pricing ready</span></div></div></section><div className="quick-order-layout container"><main><div className="quick-order-tools"><div><h2>Enter product references</h2><p>Search by exact SKU, product name or brand.</p></div><button onClick={download}><Download/> Download CSV template</button></div><div className="quick-table"><div className="quick-head"><span>SKU OR PRODUCT</span><span>MATCHED PRODUCT</span><span>CASE QTY</span><span>LINE TOTAL</span><span></span></div>{rows.map((r,i)=><div className="quick-row" key={r.id}><label><small>Line {i+1}</small><div><Search/><input value={r.query} onChange={e=>find(r.id,e.target.value)} placeholder="Enter SKU or product name"/></div>{r.query.length>2&&!r.product&&<em><AlertCircle/> No exact match yet</em>}</label><div className="quick-match">{r.product?<><img src={r.product.image}/><span><b>{r.product.name}</b><small>{r.product.sku} · Case of {r.product.casePack}</small></span></>:<span className="waiting">Awaiting product reference</span>}</div><input className="quick-qty" min="1" type="number" value={r.qty} onChange={e=>update(r.id,{qty:Math.max(1,+e.target.value)})}/><b>{r.product?`$${(r.product.price*r.product.casePack*r.qty).toFixed(2)}`:'—'}</b><button onClick={()=>setRows(x=>x.filter(a=>a.id!==r.id))}><Trash2/></button></div>)}</div><button className="add-row" onClick={()=>setRows(r=>[...r,{id:Date.now(),query:'',qty:1}])}><Plus/> Add another product line</button><div className="csv-upload"><FileUp/><div><b>Upload a completed SKU list</b><span>CSV file with SKU and CASE_QUANTITY columns · frontend preview validation</span></div><label>{uploaded||'Choose CSV file'}<input type="file" accept=".csv" onChange={e=>setUploaded(e.target.files?.[0]?.name||'')}/></label></div></main><aside><h3>Quick order summary</h3><div><span>Matched product lines</span><b>{rows.filter(r=>r.product).length}</b></div><div><span>Total cases</span><b>{rows.filter(r=>r.product).reduce((a,r)=>a+r.qty,0)}</b></div><div><span>Account pricing</span><b>{user.status==='approved'?user.tier:'Sign in required'}</b></div><hr/><div className="quick-total"><span>Merchandise estimate</span><b>${subtotal.toFixed(2)}</b></div><p>Final availability, tier pricing, tax and freight are confirmed through checkout.</p><button className="btn dark full" onClick={submit}><ShoppingBag/> Add matched lines to order</button><Link to="/shop">Browse the complete catalog →</Link></aside></div></div>}
